class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) {
            return -1;
        }

        int lo = 1;
        int hi = 0;
        for (int day : bloomDay) {
            hi = Math.max(hi, day);
        }

        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (can(bloomDay, m, k, mid)) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }

    private boolean can(int[] bloomDay, int m, int k, int day) {
        int bouquets = 0;
        int run = 0;
        for (int bloom : bloomDay) {
            if (bloom <= day) {
                run++;
                if (run == k) {
                    bouquets++;
                    run = 0;
                }
            } else {
                run = 0;
            }
        }
        return bouquets >= m;
    }
}

import java.util.Arrays;

class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) {
            return -1;
        }

        int[] days = bloomDay.clone();
        Arrays.sort(days);
        int left = 0;
        int right = days.length - 1;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (can(bloomDay, m, k, days[mid])) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }
        return days[left];
    }

    private boolean can(int[] bloomDay, int m, int k, int day) {
        int bouquets = 0;
        int run = 0;
        for (int bloom : bloomDay) {
            if (bloom <= day) {
                run++;
                if (run == k) {
                    bouquets++;
                    run = 0;
                }
            } else {
                run = 0;
            }
        }
        return bouquets >= m;
    }
}

import java.util.Arrays;

class Solution {
    private int[] parent;
    private int[] size;

    public int minDays(int[] bloomDay, int m, int k) {
        int n = bloomDay.length;
        if ((long) m * k > n) {
            return -1;
        }

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> Integer.compare(bloomDay[a], bloomDay[b]));

        parent = new int[n];
        size = new int[n];
        boolean[] active = new boolean[n];
        Arrays.fill(parent, -1);

        long bouquets = 0;
        for (int position : order) {
            active[position] = true;
            parent[position] = position;
            size[position] = 1;

            if (position > 0 && active[position - 1]) {
                bouquets -= size[find(position - 1)] / k;
                union(position, position - 1);
            }
            if (position + 1 < n && active[position + 1]) {
                bouquets -= size[find(position + 1)] / k;
                union(position, position + 1);
            }

            bouquets += size[find(position)] / k;
            if (bouquets >= m) {
                return bloomDay[position];
            }
        }
        return -1;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return;
        }
        parent[rootB] = rootA;
        size[rootA] += size[rootB];
    }
}

import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;

class Solution {
    public int minDays(int[] bloomDay, int m, int k) {
        int n = bloomDay.length;
        if ((long) m * k > n) {
            return -1;
        }

        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) {
            order[i] = i;
        }
        Arrays.sort(order, (a, b) -> Integer.compare(bloomDay[a], bloomDay[b]));

        TreeMap<Integer, Integer> intervals = new TreeMap<>();
        long bouquets = 0;
        for (int position : order) {
            int start = position;
            int end = position;

            Map.Entry<Integer, Integer> left = intervals.floorEntry(position);
            if (left != null && left.getValue() == position - 1) {
                start = left.getKey();
                bouquets -= (left.getValue() - left.getKey() + 1) / k;
                intervals.remove(left.getKey());
            }

            Map.Entry<Integer, Integer> right = intervals.ceilingEntry(position);
            if (right != null && right.getKey() == position + 1) {
                end = right.getValue();
                bouquets -= (right.getValue() - right.getKey() + 1) / k;
                intervals.remove(right.getKey());
            }

            intervals.put(start, end);
            bouquets += (end - start + 1) / k;
            if (bouquets >= m) {
                return bloomDay[position];
            }
        }
        return -1;
    }
}
